import React, { useState, useMemo, useEffect, useRef } from 'react';
import { ConcreteEntry, Project, User } from '../types';
import { Plus, Trash2, Calculator, FileSpreadsheet, UploadCloud, Building, ChevronDown, ChevronUp, Component, Droplets, HardHat, Download } from 'lucide-react';
